             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.0499999 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := 0.0249998 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.18125 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0500002 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0249997 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.24875 ns, 0.282145 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.327577 ns, 0.301504 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
