LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity MDFFHQX8 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D0_CK : VitalDelayType := DefDummyIsd;
             tipd_D1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D1_CK : VitalDelayType := DefDummyIsd;
             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_S0_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.275401 ns;
             tpw_CK_negedge : VitalDelayType := 0.200667 ns;
             tsetup_S0_CK_posedge_posedge : VitalDelayType := 0.15 ns;
             tsetup_S0_CK_negedge_posedge : VitalDelayType := 0.1875 ns;
             thold_S0_CK_posedge_posedge : VitalDelayType := -0.0187501 ns;
             thold_S0_CK_negedge_posedge : VitalDelayType := 0.0187498 ns;
             tsetup_D1_CK_posedge_posedge : VitalDelayType := 0.1625 ns;
             tsetup_D1_CK_negedge_posedge : VitalDelayType := 0.09375 ns;
             thold_D1_CK_posedge_posedge : VitalDelayType := -0.0937502 ns;
             thold_D1_CK_negedge_posedge : VitalDelayType := -0.000000000050745 ns;
             tsetup_D0_CK_posedge_posedge : VitalDelayType := 0.1625 ns;
             tsetup_D0_CK_negedge_posedge : VitalDelayType := 0.0875 ns;
             thold_D0_CK_posedge_posedge : VitalDelayType := -0.09375 ns;
             thold_D0_CK_negedge_posedge : VitalDelayType := 0.00624972 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.2479 ns, 0.275402 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D0 : in std_ulogic := 'U' ;
         D1 : in std_ulogic := 'U' ;
         S0 : in std_ulogic := 'U' ;
         Q : out std_ulogic);

   attribute VITAL_LEVEL0 of MDFFHQX8 : entity is TRUE;
end MDFFHQX8;

architecture behavioral of MDFFHQX8 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D0_dly : std_ulogic := 'X';
   SIGNAL D0_ipd : std_ulogic := 'X';
   SIGNAL D1_dly : std_ulogic := 'X';
   SIGNAL D1_ipd : std_ulogic := 'X';
   SIGNAL S0_dly : std_ulogic := 'X';
   SIGNAL S0_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D0_ipd, D0, tipd_D0 );
   VitalWireDelay( D1_ipd, D1, tipd_D1 );
   VitalWireDelay( S0_ipd, S0, tipd_S0 );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D0_dly, D0_ipd, tisd_D0_CK );
   VitalSignalDelay( D1_dly, D1_ipd, tisd_D1_CK );
   VitalSignalDelay( S0_dly, S0_ipd, tisd_S0_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D0_dly, D1_dly, S0_dly)

      --timing checks section variables
      VARIABLE Tviol_S0_CK : std_ulogic := '0';
      VARIABLE TimeMarker_S0_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D1_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D1_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D0_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D0_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE QBINT : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE D0_EQ_0_AN_D1_EQ_1 : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE D0_EQ_1_AN_D1_EQ_0 : std_ulogic;
      VARIABLE S0_EQ_1 : std_ulogic;
      VARIABLE S0_EQ_0 : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE D0_EQ_0_AN_D1_EQ_0_AN_S0_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => S0_dly,
                    TestSignalName => "S0",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_S0_CK_posedge_posedge,
                    SetupLow       => tsetup_S0_CK_negedge_posedge,
                    HoldHigh       => thold_S0_CK_posedge_posedge,
                    HoldLow        => thold_S0_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D0_EQ_0_AN_D1_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX8",
                    TimingData     => TimeMarker_S0_CK,
                    Violation      => Tviol_S0_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D1_dly,
                    TestSignalName => "D1",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D1_CK_posedge_posedge,
                    SetupLow       => tsetup_D1_CK_negedge_posedge,
                    HoldHigh       => thold_D1_CK_posedge_posedge,
                    HoldLow        => thold_D1_CK_negedge_posedge,
                    CheckEnabled   => To_X01(S0_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX8",
                    TimingData     => TimeMarker_D1_CK,
                    Violation      => Tviol_D1_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D0_dly,
                    TestSignalName => "D0",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D0_CK_posedge_posedge,
                    SetupLow       => tsetup_D0_CK_negedge_posedge,
                    HoldHigh       => thold_D0_CK_posedge_posedge,
                    HoldLow        => thold_D0_CK_negedge_posedge,
                    CheckEnabled   => To_X01(S0_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX8",
                    TimingData     => TimeMarker_D0_CK,
                    Violation      => Tviol_D0_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/MDFFHQX8",
                    CheckEnabled   => To_X01(D0_EQ_0_AN_D1_EQ_0_AN_S0_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_S0_CK OR
                        Tviol_D1_CK OR
                        Tviol_D0_CK OR
                        PWviol_CK );

          n0_D := VitalMUX2(D1_dly, D0_dly, S0_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          n1_var := VitalINV(D0_dly);
          D0_EQ_0_AN_D1_EQ_1 := VitalAND2(n1_var, D1_dly);

          n2_var := VitalINV(D1_dly);
          D0_EQ_1_AN_D1_EQ_0 := VitalAND2(D0_dly, n2_var);

          S0_EQ_1 := VitalBUF(S0_dly);

          S0_EQ_0 := VitalINV(S0_dly);

          n3_var := VitalINV(D0_dly);
          n4_var := VitalINV(D1_dly);
          n5_var := VitalAND2(n3_var, n4_var);
          n6_var := VitalINV(S0_dly);
          D0_EQ_0_AN_D1_EQ_0_AN_S0_EQ_0 := VitalAND2(n5_var, n6_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
