             tpd_S0_Y_posedge : VitalDelayType01 := (0.18289 ns, 0.222161 ns);
             tpd_S0_Y_negedge : VitalDelayType01 := (0.218674 ns, 0.183195 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
