                             TRUE),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE),
                      2 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_posedge,
                             To_X01(S0_ipd) /= '1'),
                      3 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_negedge,
                             To_X01(S0_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
