                             tpd_S1_Y_negedge,
                             To_X01(S1_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


