entity SDFFQX1 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tipd_SI : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SI_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.30187 ns;
             tpw_CK_negedge : VitalDelayType := 0.192036 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.2 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.125 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.01875 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.1875 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.21875 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0437502 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.20625 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.125 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.01875 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.266267 ns, 0.30187 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
         Q : out std_ulogic);

   attribute VITAL_LEVEL0 of SDFFQX1 : entity is TRUE;
end SDFFQX1;

architecture behavioral of SDFFQX1 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D_dly : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';
   SIGNAL SI_dly : std_ulogic := 'X';
   SIGNAL SI_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
   VitalWireDelay( SI_ipd, SI, tipd_SI );
