             tpw_CK_negedge : VitalDelayType := 0.199974 ns;
             tpw_RN_negedge : VitalDelayType := 0.179708 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.125 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0124999 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.20625 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.24375 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0374999 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := 0.000000000121396 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.125 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0124999 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.324322 ns, 0.289644 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.334729 ns, 0.37526 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.117918 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.16298 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         RN : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
