          RN_EQ_1_AN_SE_EQ_0 := VitalAND2(RN_dly, n3_var);

          n4_var := VitalINV(D_dly);
          n5_var := VitalAND2(n4_var, RN_dly);
          n6_var := VitalINV(SE_dly);
          n7_var := VitalAND2(n5_var, n6_var);
          n8_var := VitalINV(SI_dly);
          D_EQ_0_AN_RN_EQ_1_AN_SE_EQ_0_AN_SI_EQ_0 := VitalAND2(n7_var, n8_var);

          n9_var := VitalINV(D_dly);
          n10_var := VitalINV(SE_dly);
          n11_var := VitalAND2(n9_var, n10_var);
          n12_var := VitalINV(SI_dly);
          D_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 := VitalAND2(n11_var, n12_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0'),
                      1 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q_negedge,
                             To_X01(RN_dly) /= '1')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0'),
                      1 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN_negedge,
                             To_X01(RN_dly) /= '1')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


