             tpw_CK_negedge : VitalDelayType := 0.209138 ns;
             tpw_RN_negedge : VitalDelayType := 0.229607 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.1375 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0187499 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.20625 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.2375 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0375001 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.00624982 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.1375 ns;
