             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0187501 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := 0.0187499 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.15 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.00625022 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.298055 ns, 0.337257 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.374503 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.228404 ns, 0 ns);
