             tpw_CK_negedge : VitalDelayType := 0.241441 ns;
             tpw_SN_negedge : VitalDelayType := 0.366727 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.21875 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.2125 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.1375 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.03125 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.23125 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.2375 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0499998 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0187501 ns;
