             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.20625 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.1375 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.13125 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0249998 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.19375 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.25625 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0499997 ns;
