             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.33125 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.15 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.225 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.0312497 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.325 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.14375 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.21875 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0249999 ns;
