             thold_RN_CK_posedge_posedge : VitalDelayType := -0.425 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.15 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.49375 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.35 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.2375 ns;
