entity SEDFFX2 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_E : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_E_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tipd_SI : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SI_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.361029 ns;
             tpw_CK_negedge : VitalDelayType := 0.208427 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.225 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.15 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.14375 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0249999 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.2125 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0187502 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.28125 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.05625 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.3625 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.30625 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.25625 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0499998 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.38125 ns;
