             thold_SI_CK_negedge_posedge : VitalDelayType := 0.00000000000410282 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.15 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.20625 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0312503 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := 0.00624988 ns;
             tsetup_S0_CK_posedge_posedge : VitalDelayType := 0.26875 ns;
             tsetup_S0_CK_negedge_posedge : VitalDelayType := 0.3 ns;
             thold_S0_CK_posedge_posedge : VitalDelayType := -0.0625001 ns;
             thold_S0_CK_negedge_posedge : VitalDelayType := -0.0250001 ns;
             tsetup_D1_CK_posedge_posedge : VitalDelayType := 0.28125 ns;
             tsetup_D1_CK_negedge_posedge : VitalDelayType := 0.1875 ns;
             thold_D1_CK_posedge_posedge : VitalDelayType := -0.1875 ns;
             thold_D1_CK_negedge_posedge : VitalDelayType := -0.0375 ns;
             tsetup_D0_CK_posedge_posedge : VitalDelayType := 0.28125 ns;
             tsetup_D0_CK_negedge_posedge : VitalDelayType := 0.1875 ns;
             thold_D0_CK_posedge_posedge : VitalDelayType := -0.1875 ns;
