             tsetup_RN_G_posedge_negedge : VitalDelayType := 0.26875 ns;
             thold_RN_G_posedge_negedge : VitalDelayType := -0.23125 ns;
             tsetup_D_G_posedge_negedge : VitalDelayType := 0.0874999 ns;
             tsetup_D_G_negedge_negedge : VitalDelayType := 0.13125 ns;
             thold_D_G_posedge_negedge : VitalDelayType := -0.0499999 ns;
             thold_D_G_negedge_negedge : VitalDelayType := -0.0875 ns;
             tpd_D_Q : VitalDelayType01 := (0.250121 ns, 0.292835 ns);
             tpd_D_QN : VitalDelayType01 := (0.274018 ns, 0.233713 ns);
             tpd_G_Q_posedge : VitalDelayType01 := (0.418471 ns, 0.440277 ns);
             tpd_G_QN_posedge : VitalDelayType01 := (0.421626 ns, 0.401977 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.352443 ns);
             tpd_RN_Q_posedge : VitalDelayType01 := (0.424064 ns, 0 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.33371 ns, 0 ns);
             tpd_RN_QN_posedge : VitalDelayType01 := (0 ns, 0.407589 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.115648 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.185498 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.0989107 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.166709 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         D : in std_ulogic := 'U' ;
         G : in std_ulogic := 'U' ;
         RN : in std_ulogic := 'U' ;
         SN : in std_ulogic := 'U' ;
