             thold_D_G_posedge_negedge : VitalDelayType := -0.04375 ns;
             thold_D_G_negedge_negedge : VitalDelayType := -0.0687499 ns;
             tpd_D_Q : VitalDelayType01 := (0.238052 ns, 0.236724 ns);
             tpd_D_QN : VitalDelayType01 := (0.216651 ns, 0.228172 ns);
             tpd_G_Q_posedge : VitalDelayType01 := (0.310145 ns, 0.27993 ns);
             tpd_G_QN_posedge : VitalDelayType01 := (0.260018 ns, 0.300204 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         D : in std_ulogic := 'U' ;
         G : in std_ulogic := 'U' ;
