             tisd_S0_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.304662 ns;
             tpw_CK_negedge : VitalDelayType := 0.195856 ns;
             tsetup_S0_CK_posedge_posedge : VitalDelayType := 0.15 ns;
             tsetup_S0_CK_negedge_posedge : VitalDelayType := 0.1875 ns;
             thold_S0_CK_posedge_posedge : VitalDelayType := -0.0312501 ns;
             thold_S0_CK_negedge_posedge : VitalDelayType := 0.00625009 ns;
