             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y : VitalDelayType01 := (0.339346 ns, 0.324666 ns);
             tpd_B_Y : VitalDelayType01 := (0.340049 ns, 0.327349 ns);
             tpd_C_Y : VitalDelayType01 := (0.330526 ns, 0.317815 ns);
             tpd_D_Y : VitalDelayType01 := (0.327234 ns, 0.317612 ns);
             tpd_S0_Y_posedge : VitalDelayType01 := (0.320256 ns, 0.363511 ns);
             tpd_S0_Y_negedge : VitalDelayType01 := (0.37112 ns, 0.308264 ns);
             tpd_S1_Y_posedge : VitalDelayType01 := (0.226499 ns, 0.247755 ns);
             tpd_S1_Y_negedge : VitalDelayType01 := (0.236492 ns, 0.229494 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

