   SIGNAL C_ipd : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL S0_ipd : std_ulogic := 'X';
   SIGNAL S1_ipd : std_ulogic := 'X';

begin

--Input Path Delays
