      VARIABLE n0_var : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE Y_zd : std_ulogic;

      -- path delay section variables
      VARIABLE Y_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          n0_var := VitalMUX2(D_ipd, C_ipd, S0_ipd);
          n1_var := VitalMUX2(B_ipd, A_ipd, S0_ipd);
          n2_var := VitalMUX2(n0_var, n1_var, S1_ipd);
          Y_zd := VitalINV(n2_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y,
                             TRUE),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE),
                      2 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y,
                             TRUE),
                      3 => ( D_ipd'LAST_EVENT,
                             tpd_D_Y,
                             TRUE),
                      4 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_posedge,
                             To_X01(S0_ipd) /= '1'),
                      5 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_negedge,
                             To_X01(S0_ipd) /= '0'),
                      6 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_posedge,
                             To_X01(S1_ipd) /= '1'),
                      7 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_negedge,
                             To_X01(S1_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


