             trecovery_SN_CK_posedge_posedge : VitalDelayType := -0.00625018 ns;
             tremoval_SN_CK_posedge_posedge : VitalDelayType := 0.0937499 ns;
             tpw_CK_posedge : VitalDelayType := 0.305116 ns;
             tpw_CK_negedge : VitalDelayType := 0.230961 ns;
             tpw_SN_negedge : VitalDelayType := 0.199844 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.16875 ns;
