             thold_SI_CK_posedge_posedge : VitalDelayType := -0.1 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := 0.000000000121421 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.16875 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.19375 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.03125 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := 0.0125 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.16875 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.1375 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.00000000000995512 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.246267 ns, 0.305117 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.197541 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
