             trecovery_SN_CK_posedge_posedge : VitalDelayType := 0.0374999 ns;
             tremoval_SN_CK_posedge_posedge : VitalDelayType := 0.06875 ns;
             tpw_CK_posedge : VitalDelayType := 0.356969 ns;
             tpw_CK_negedge : VitalDelayType := 0.249403 ns;
