             thold_SI_CK_negedge_posedge : VitalDelayType := -0.025 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.2375 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.25 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0437499 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0124999 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.2375 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.21875 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.1375 ns;
