             tipd_RN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_RN : VitalDelayType := DefDummyIcd;
             tipd_SN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SN_RN : VitalDelayType := DefDummyIsd;
             trecovery_SN_RN_posedge_posedge : VitalDelayType := 0.0249998 ns;
             tremoval_SN_RN_posedge_posedge : VitalDelayType := 0.01875 ns;
             trecovery_SN_G_posedge_negedge : VitalDelayType := 0.025 ns;
             tremoval_SN_G_posedge_negedge : VitalDelayType := 0.0375 ns;
             tpw_G_posedge : VitalDelayType := 0.448416 ns;
             tpw_RN_negedge : VitalDelayType := 0.366981 ns;
             tpw_SN_negedge : VitalDelayType := 0.196798 ns;
             tsetup_RN_G_posedge_negedge : VitalDelayType := 0.225 ns;
             thold_RN_G_posedge_negedge : VitalDelayType := -0.19375 ns;
             tsetup_D_G_posedge_negedge : VitalDelayType := 0.0874998 ns;
             tsetup_D_G_negedge_negedge : VitalDelayType := 0.125 ns;
             thold_D_G_posedge_negedge : VitalDelayType := -0.05 ns;
             thold_D_G_negedge_negedge : VitalDelayType := -0.08125 ns;
             tpd_D_Q : VitalDelayType01 := (0.28379 ns, 0.349937 ns);
             tpd_D_QN : VitalDelayType01 := (0.338946 ns, 0.280099 ns);
             tpd_G_Q_posedge : VitalDelayType01 := (0.407908 ns, 0.448416 ns);
