             tpd_RN_QN_posedge : VitalDelayType01 := (0 ns, 0.410799 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.175137 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.261218 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.171271 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.250164 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
