                             tpd_B_Y_negedge,
                             To_X01(B_ipd) /= '0'),
                      4 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y_posedge,
                             To_X01(C_ipd) /= '1'),
                      5 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y_negedge,
                             To_X01(C_ipd) /= '0')),
               GlitchData => Y_GlitchData,
