                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/SEDFFTRX1",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_RN_CK OR
                        Tviol_E_CK OR
                        Tviol_D_CK OR
                        PWviol_CK );

          n1_var := VitalINV(D_dly);
          n2_var := VitalAND2(n1_var, E_dly);
          n3_var := VitalINV(n2_var);
          n4_var := VitalINV(E_dly);
          n5_var := VitalAND2(n4_var, QBINT);
          n6_var := VitalINV(n5_var);
          n7_var := VitalAND2(n3_var, n6_var);
          n8_var := VitalAND2(n7_var, RN_dly);
          n0_D := VitalMUX2(SI_dly, n8_var, SE_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          QN_zd := VitalBUF(QBINT);

          SE_EQ_1 := VitalBUF(SE_dly);

          n9_var := VitalINV(D_dly);
          n10_var := VitalINV(E_dly);
          n11_var := VitalAND2(n9_var, n10_var);
          n12_var := VitalINV(RN_dly);
          n13_var := VitalAND2(n11_var, n12_var);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1 := VitalAND2(n13_var, SI_dly);

          n14_var := VitalINV(D_dly);
          n15_var := VitalINV(E_dly);
          n16_var := VitalAND2(n14_var, n15_var);
          n17_var := VitalAND2(n16_var, RN_dly);
          n18_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n17_var, n18_var);

          n19_var := VitalAND2(D_dly, E_dly);
          n20_var := VitalAND2(n19_var, RN_dly);
          n21_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n20_var, n21_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n22_var := VitalINV(SE_dly);
          RN_EQ_1_AN_SE_EQ_0 := VitalAND2(RN_dly, n22_var);

          n23_var := VitalAND2(E_dly, RN_dly);
          n24_var := VitalINV(SE_dly);
          E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0 := VitalAND2(n23_var, n24_var);

          n25_var := VitalINV(D_dly);
          n26_var := VitalINV(E_dly);
          n27_var := VitalAND2(n25_var, n26_var);
          n28_var := VitalINV(RN_dly);
          n29_var := VitalAND2(n27_var, n28_var);
          n30_var := VitalINV(SE_dly);
          n31_var := VitalAND2(n29_var, n30_var);
          n32_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 := VitalAND2(n31_var, n32_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


