                    HeaderMsg      => InstancePath & "/DFFSHQX1",
                    CheckEnabled   => To_X01(D_EQ_0_AN_SN_EQ_1) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

