             thold_D_GN_posedge_posedge : VitalDelayType := -0.0125 ns;
             thold_D_GN_negedge_posedge : VitalDelayType := -0.04375 ns;
             tpd_D_Q : VitalDelayType01 := (0.27142 ns, 0.333741 ns);
