             tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y : VitalDelayType01 := (0.193342 ns, 0.207958 ns);
             tpd_B_Y : VitalDelayType01 := (0.196544 ns, 0.209371 ns);
             tpd_S0_Y_posedge : VitalDelayType01 := (0.218803 ns, 0.194909 ns);
             tpd_S0_Y_negedge : VitalDelayType01 := (0.181309 ns, 0.227309 ns);

