      BEGIN
          -- Functionality section
          n0_var := VitalMUX2(B_ipd, A_ipd, S0_ipd);
          Y_zd := VitalINV(n0_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
