             tpd_A_Y_negedge : VitalDelayType01 := (0.277425 ns, 0.259987 ns);
             tpd_B_Y_posedge : VitalDelayType01 := (0.219259 ns, 0.250689 ns);
             tpd_B_Y_negedge : VitalDelayType01 := (0.234249 ns, 0.23026 ns);

