               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y_posedge,
                             To_X01(A_ipd) /= '1'),
                      1 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y_negedge,
                             To_X01(A_ipd) /= '0'),
                      2 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y_posedge,
                             To_X01(B_ipd) /= '1'),
                      3 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y_negedge,
                             To_X01(B_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
