             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.270665 ns;
             tpw_CK_negedge : VitalDelayType := 0.222566 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0812501 ns;
