             thold_D_CK_posedge_posedge : VitalDelayType := -0.0375001 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0687498 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.238521 ns, 0.270665 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         Q : out std_ulogic);

