          n6_var := VitalINV(n5_var);
          n7_var := VitalAND2(n3_var, n6_var);
          n0_D := VitalAND2(n7_var, RN_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          QN_zd := VitalBUF(QBINT);

          n8_var := VitalINV(D_dly);
          n9_var := VitalINV(E_dly);
          D_EQ_0_AN_E_EQ_0 := VitalAND2(n8_var, n9_var);

          D_EQ_1_AN_E_EQ_1 := VitalAND2(D_dly, E_dly);

          RN_EQ_1 := VitalBUF(RN_dly);

          E_EQ_1_AN_RN_EQ_1 := VitalAND2(E_dly, RN_dly);

          n10_var := VitalINV(D_dly);
          n11_var := VitalINV(E_dly);
          n12_var := VitalAND2(n10_var, n11_var);
          n13_var := VitalINV(RN_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0 := VitalAND2(n12_var, n13_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity SEDFFHQX1 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_E : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_E_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tipd_SI : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SI_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.308169 ns;
             tpw_CK_negedge : VitalDelayType := 0.196747 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.16875 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.1 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.1125 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0124999 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.15625 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.00624987 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.2125 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.04375 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.26875 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.24375 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.19375 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0375001 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.28125 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.2 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.2 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0562501 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.263508 ns, 0.308165 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
         Q : out std_ulogic);

   attribute VITAL_LEVEL0 of SEDFFHQX1 : entity is TRUE;
end SEDFFHQX1;

architecture behavioral of SEDFFHQX1 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D_dly : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL E_dly : std_ulogic := 'X';
   SIGNAL E_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';
   SIGNAL SI_dly : std_ulogic := 'X';
   SIGNAL SI_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( E_ipd, E, tipd_E );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
   VitalWireDelay( SI_ipd, SI, tipd_SI );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D_dly, D_ipd, tisd_D_CK );
   VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
   VitalSignalDelay( SE_dly, SE_ipd, tisd_SE_CK );
   VitalSignalDelay( SI_dly, SI_ipd, tisd_SI_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D_dly, E_dly, SE_dly, SI_dly)

      --timing checks section variables
      VARIABLE Tviol_SI_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SI_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_SE_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_E_CK : std_ulogic := '0';
      VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE QBINT : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE SE_EQ_1 : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0 : std_ulogic;
      VARIABLE n7_var : std_ulogic;
      VARIABLE n8_var : std_ulogic;
      VARIABLE n9_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n10_var : std_ulogic;
      VARIABLE n11_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_1_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n12_var : std_ulogic;
      VARIABLE n13_var : std_ulogic;
      VARIABLE D_EQ_1_AN_E_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE SE_EQ_0 : std_ulogic;
      VARIABLE n14_var : std_ulogic;
      VARIABLE E_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n15_var : std_ulogic;
      VARIABLE n16_var : std_ulogic;
      VARIABLE n17_var : std_ulogic;
      VARIABLE n18_var : std_ulogic;
      VARIABLE n19_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => SI_dly,
                    TestSignalName => "SI",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SI_CK_posedge_posedge,
                    SetupLow       => tsetup_SI_CK_negedge_posedge,
                    HoldHigh       => thold_SI_CK_posedge_posedge,
                    HoldLow        => thold_SI_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFHQX1",
                    TimingData     => TimeMarker_SI_CK,
                    Violation      => Tviol_SI_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => SE_dly,
                    TestSignalName => "SE",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SE_CK_posedge_posedge,
                    SetupLow       => tsetup_SE_CK_negedge_posedge,
                    HoldHigh       => thold_SE_CK_posedge_posedge,
                    HoldLow        => thold_SE_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFHQX1",
                    TimingData     => TimeMarker_SE_CK,
                    Violation      => Tviol_SE_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => E_dly,
                    TestSignalName => "E",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_E_CK_posedge_posedge,
                    SetupLow       => tsetup_E_CK_negedge_posedge,
                    HoldHigh       => thold_E_CK_posedge_posedge,
                    HoldLow        => thold_E_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFHQX1",
                    TimingData     => TimeMarker_E_CK,
                    Violation      => Tviol_E_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D_dly,
                    TestSignalName => "D",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D_CK_posedge_posedge,
                    SetupLow       => tsetup_D_CK_negedge_posedge,
                    HoldHigh       => thold_D_CK_posedge_posedge,
                    HoldLow        => thold_D_CK_negedge_posedge,
                    CheckEnabled   => To_X01(E_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFHQX1",
                    TimingData     => TimeMarker_D_CK,
                    Violation      => Tviol_D_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/SEDFFHQX1",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_E_CK OR
                        Tviol_D_CK OR
                        PWviol_CK );

          n1_var := VitalINV(QBINT);
          n2_var := VitalMUX2(D_dly, n1_var, E_dly);
          n0_D := VitalMUX2(SI_dly, n2_var, SE_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          SE_EQ_1 := VitalBUF(SE_dly);

          n3_var := VitalINV(D_dly);
          n4_var := VitalINV(E_dly);
          n5_var := VitalAND2(n3_var, n4_var);
          n6_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0 := VitalAND2(n5_var, n6_var);

          n7_var := VitalINV(D_dly);
          n8_var := VitalINV(E_dly);
          n9_var := VitalAND2(n7_var, n8_var);
          D_EQ_0_AN_E_EQ_0_AN_SI_EQ_1 := VitalAND2(n9_var, SI_dly);

          n10_var := VitalINV(D_dly);
          n11_var := VitalAND2(n10_var, E_dly);
          D_EQ_0_AN_E_EQ_1_AN_SI_EQ_1 := VitalAND2(n11_var, SI_dly);

          n12_var := VitalAND2(D_dly, E_dly);
          n13_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_SI_EQ_0 := VitalAND2(n12_var, n13_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n14_var := VitalINV(SE_dly);
          E_EQ_1_AN_SE_EQ_0 := VitalAND2(E_dly, n14_var);

          n15_var := VitalINV(D_dly);
          n16_var := VitalINV(E_dly);
          n17_var := VitalAND2(n15_var, n16_var);
          n18_var := VitalAND2(n17_var, SE_dly);
          n19_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0 := VitalAND2(n18_var, n19_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity CLKAND2X4 is
   generic (
             tipd_A : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y : VitalDelayType01 := (0.0941471 ns, 0.0937251 ns);
             tpd_B_Y : VitalDelayType01 := (0.0897137 ns, 0.0888331 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
         B : in std_ulogic := 'U' ;
         Y : out std_ulogic);

   attribute VITAL_LEVEL0 of CLKAND2X4 : entity is TRUE;
end CLKAND2X4;

architecture behavioral of CLKAND2X4 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL A_ipd : std_ulogic := 'X';
   SIGNAL B_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( A_ipd, A, tipd_A );
   VitalWireDelay( B_ipd, B, tipd_B );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd)


      -- functionality section variables
      VARIABLE Y_zd : std_ulogic;

      -- path delay section variables
      VARIABLE Y_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          Y_zd := VitalAND2(A_ipd, B_ipd);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y,
                             TRUE),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE)),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity OAI211XL is
   generic (
             tipd_A0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_A1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_B0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_C0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A0_Y : VitalDelayType01 := (0.313509 ns, 0.541924 ns);
             tpd_A1_Y : VitalDelayType01 := (0.306288 ns, 0.521068 ns);
             tpd_B0_Y : VitalDelayType01 := (0.146063 ns, 0.474556 ns);
             tpd_C0_Y : VitalDelayType01 := (0.143342 ns, 0.465417 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A0 : in std_ulogic := 'U' ;
         A1 : in std_ulogic := 'U' ;
         B0 : in std_ulogic := 'U' ;
         C0 : in std_ulogic := 'U' ;
         Y : out std_ulogic);

   attribute VITAL_LEVEL0 of OAI211XL : entity is TRUE;
end OAI211XL;

architecture behavioral of OAI211XL is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL A0_ipd : std_ulogic := 'X';
   SIGNAL A1_ipd : std_ulogic := 'X';
   SIGNAL B0_ipd : std_ulogic := 'X';
   SIGNAL C0_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( A0_ipd, A0, tipd_A0 );
   VitalWireDelay( A1_ipd, A1, tipd_A1 );
   VitalWireDelay( B0_ipd, B0, tipd_B0 );
   VitalWireDelay( C0_ipd, C0, tipd_C0 );
END BLOCK;

VITALBehavior : PROCESS (A0_ipd, A1_ipd, B0_ipd, C0_ipd)


      -- functionality section variables
      VARIABLE n0_var : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE Y_zd : std_ulogic;

      -- path delay section variables
      VARIABLE Y_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          n0_var := VitalOR2(A0_ipd, A1_ipd);
          n1_var := VitalAND2(n0_var, B0_ipd);
          n2_var := VitalAND2(n1_var, C0_ipd);
          Y_zd := VitalINV(n2_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A0_ipd'LAST_EVENT,
                             tpd_A0_Y,
                             TRUE),
                      1 => ( A1_ipd'LAST_EVENT,
                             tpd_A1_Y,
                             TRUE),
                      2 => ( B0_ipd'LAST_EVENT,
                             tpd_B0_Y,
                             TRUE),
                      3 => ( C0_ipd'LAST_EVENT,
                             tpd_C0_Y,
                             TRUE)),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


